{"code": "export async function main(input: { since: string }) {
  let cursor: string | undefined = undefined;
  const pageSizes: number[] = [];
  const perPageDates: { page: number; first: string; last: string; n: number }[] = [];
  let excluded = 0;
  let earliest = "";
  let page = 0;
  const seen = new Set<string>();
  let dup = 0;
  while (true) {
    const res = await sdk.github.listCommits({ since: input.since, cursor });
    page++;
    pageSizes.push(res.commits.length);
    for (const c of res.commits) {
      if (seen.has(c.sha)) dup++;
      seen.add(c.sha);
      if (new Date(c.committedAt).getTime() < new Date(input.since).getTime()) excluded++;
      if (!earliest || new Date(c.committedAt) < new Date(earliest)) earliest = c.committedAt;
    }
    if (res.commits.length) perPageDates.push({ page, first: res.commits[0].committedAt, last: res.commits[res.commits.length - 1].committedAt, n: res.commits.length });
    if (!res.nextCursor) break;
    cursor = res.nextCursor;
    if (page > 1000) throw new Error("too many");
  }
  return { pages: page, pageSizes, excluded, earliest, dup, perPageDates, unique: seen.size };
}", "input": {"since": "2026-09-01T00:00:00Z"}}
